{"type":"code","language":"c","source":"/* 树的孩子兄弟表示法（First-Child / Next-Sibling）*/
typedef struct Node {
    int data;                  // 节点数据域
    struct Node *firstChild;   // 指向第一个孩子节点
    struct Node *nextSibling;  // 指向下一个兄弟节点
} Node;

/* 具象锚点：用该结构体表示根为 A，A 有孩子 B、C，B 有孩子 D 的树 */
Node a = {'A', NULL, NULL};
Node b = {'B', NULL, NULL};
Node c = {'C', NULL, NULL};
Node d = {'D', NULL, NULL};
a.firstChild = &b;   // A 的第一个孩子是 B
b.nextSibling = &c;  // B 的下一个兄弟是 C
b.firstChild = &d;   // B 的第一个孩子是 D","filename":"tree_node.c","caption":"孩子兄弟表示法的 C 结构体与最小建树示例"}
